create or replace function public.factory_update_run_delivery_status(p_run_id uuid,p_status text,p_candidate_commit text default null) returns jsonb language plpgsql security invoker set search_path='' as $$ declare v_task_id uuid;v_project_id uuid;begin select r.task_id,t.project_id into v_task_id,v_project_id from public.factory_runs r join public.factory_tasks t on t.id=r.task_id where r.id=p_run_id for update of r;if v_task_id is null then raise exception 'run not found';end if;update public.factory_runs set status=p_status,candidate_commit=coalesce(p_candidate_commit,candidate_commit),finished_at=case when p_status in ('completed','failed','merged') then now() else finished_at end where id=p_run_id;insert into public.factory_audit_events(project_id,task_id,run_id,actor_type,actor_ref,event_type,payload) values(v_project_id,v_task_id,p_run_id,'system','github-loop','run.status.updated',jsonb_build_object('status',p_status,'candidate_commit',p_candidate_commit));return jsonb_build_object('run_id',p_run_id,'task_id',v_task_id,'status',p_status,'candidate_commit',p_candidate_commit);end;$$;
revoke all on function public.factory_update_run_delivery_status(uuid,text,text) from public,anon,authenticated;grant execute on function public.factory_update_run_delivery_status(uuid,text,text) to service_role;
create or replace function public.factory_record_delivery_tool_usage(p_run_id uuid,p_tool_family text,p_operation text,p_usage_units numeric,p_estimated_cost numeric,p_metadata jsonb) returns bigint language plpgsql security invoker set search_path='' as $$ declare v_id bigint;begin if not exists(select 1 from public.factory_runs where id=p_run_id) then raise exception 'run not found';end if;insert into public.factory_tool_usage(run_id,tool_family,operation,usage_units,estimated_cost,metadata) values(p_run_id,p_tool_family,p_operation,p_usage_units,p_estimated_cost,coalesce(p_metadata,'{}'::jsonb)) returning id into v_id;return v_id;end;$$;
revoke all on function public.factory_record_delivery_tool_usage(uuid,text,text,numeric,numeric,jsonb) from public,anon,authenticated;grant execute on function public.factory_record_delivery_tool_usage(uuid,text,text,numeric,numeric,jsonb) to service_role;
